class Solution { public:int maximumWhiteTiles(vector<vector<int>>& tiles,int carpetLen){sort(tiles.begin(),tiles.end());int right=0,full=0,answer=0;for(int left=0;left<(int)tiles.size();++left){int end=tiles[left][0]+carpetLen-1;while(right<(int)tiles.size()&&tiles[right][1]<=end){full+=tiles[right][1]-tiles[right][0]+1;++right;}int covered=full;if(right<(int)tiles.size()&&tiles[right][0]<=end)covered+=end-tiles[right][0]+1;answer=max(answer,covered);if(right>left)full-=tiles[left][1]-tiles[left][0]+1;else right=left+1;}return min(answer,carpetLen);} };
